// ninekit-phaser.js - generated by ninekit __NINEKIT_VERSION__ from manifest "__NINEKIT_NAME__". Do not edit:
// re-export with `ninekit export ninekit.json --target phaser -o DIR`.
//
// Phaser 3.60+ (scene.add.nineslice). Units: dp = Phaser world units. Every texture is loaded at ONE scale (texture
// px per dp) and drawn at 1/scale, so widths, heights and positions are in dp. Pick the scale that matches the
// canvas' backing store (window.devicePixelRatio x any zoom) for 1:1 texels.
//
//   import { preloadNinekit, addNinekit } from './ninekit-phaser.js';
//   preload() { preloadNinekit(this); }                    // or preloadNinekit(this, 'ui/', { scale: 2 })
//   create()  { const b = addNinekit(this, 160, 90, 'btn_mint', 180, 59, { button: true }); }
//
// addNinekit returns a Container at (x, y); (x, y) is the point at (originX, originY) of the piece's LOGICAL rect
// (the sprite minus its overhang, e.g. a drop shadow), default its centre. On a `fixed` axis the art keeps its
// natural length, centred on the logical rect, whatever size you give (the content still lays out in the rect). Children, bottom to top: one per stacked
// output - a NineSlice (texture-px slices, scaled 1/scale), an Image for pieces drawn whole, or for `tile` axes a
// group of Images / TileSprites repeating the middle a whole number of times (like CSS border-image `round`).
// container.ninekit: { resize(w, h), setPressed(on), contentRect(), content, addContent(...objs), layers, ... }.
// Labels and other children go in `content` (addContent; container-local coordinates, like contentRect()), above
// the layers. `content` insets are measured from the canvas edges (the sprite including its overhang).
// Frame/face pieces: setPressed(true) scales the `face` AND the content together toward the logical centre (the
// body) by opts.press (default 0.92); the frame stays. opts.button: true wires pointer down/up/out to it.
// Shade pieces: opts.ramp = [[t, '#rrggbb'], ...] maps the greys (t = shade 0..1) through the ramp into a cached
// recoloured texture.

const DATA = __NINEKIT_DATA__;
const MODULE_BASE = new URL('.', import.meta.url).href;
let currentScale = null;

export const manifest = DATA;
export const PRESS = 0.92;

/** The manifest scale for a device pixel ratio: the smallest scale >= dpr, else the largest. */
export function pickScale(dpr) {
  const d = dpr ?? (globalThis.devicePixelRatio || 1);
  const scales = DATA.scales.map(Number).sort((a, b) => a - b);
  for (const s of scales) if (s >= d - 1e-6) return s;
  return scales[scales.length - 1];
}

function skey(scale) {
  return String(Number(scale));
}

function outputsOf(p) {
  return p.composite ? p.layers.concat([p.composite]) : p.layers;
}

/** Queues every output of every piece (or opts.only) as a texture at one scale. Call from a scene's preload().
 *  baseUrl: where the PNGs are (default: this module's folder). Returns the scale used. */
export function preloadNinekit(scene, baseUrl, opts = {}) {
  const scale = opts.scale != null ? Number(opts.scale) : pickScale(opts.dpr);
  const k = skey(scale);
  if (!DATA.scales.map(Number).includes(scale)) {
    throw new Error(`ninekit ${DATA.name}: no scale ${k} (has ${DATA.scales.join(', ')})`);
  }
  let base = baseUrl == null ? MODULE_BASE : String(baseUrl);
  if (base && !base.endsWith('/')) base += '/';
  const only = opts.only ? new Set(opts.only) : null;
  for (const [name, p] of Object.entries(DATA.pieces)) {
    if (only && !only.has(name)) continue;
    for (const o of outputsOf(p)) {
      const f = p.outputs[o][k];
      if (f && !scene.textures.exists(f.key)) scene.load.image(f.key, base + f.file);
    }
  }
  currentScale = scale;
  return scale;
}

/** A Container drawing piece [name] with a logical size of width x height dp (default: the piece's own). */
export function addNinekit(scene, x, y, name, width, height, opts = {}) {
  const p = DATA.pieces[name];
  if (!p) throw new Error(`ninekit ${DATA.name}: no piece ${name}`);
  const scale = opts.scale != null ? Number(opts.scale) : (currentScale ?? pickScale());
  const k = skey(scale);
  const oh = p.overhang || [0, 0, 0, 0];
  const c = scene.add.container(x, y);
  const nk = {
    manifest: DATA.name, name, piece: p, scale, container: c,
    width: width ?? Math.max(0, p.size[0] - oh[0] - oh[2]),
    height: height ?? Math.max(0, p.size[1] - oh[1] - oh[3]),
    originX: opts.originX ?? 0.5, originY: opts.originY ?? 0.5,
    press: opts.press ?? PRESS, pressed: false, layers: {},
  };
  const outs = opts.composite && p.composite ? [p.composite] : p.layers;
  for (const o of outs) {
    const f = p.outputs[o][k];
    if (!f) throw new Error(`ninekit ${DATA.name}: ${name}/${o} has no scale ${k}`);
    if (!scene.textures.exists(f.key)) {
      throw new Error(`ninekit: texture ${f.key} is not loaded (call preloadNinekit with scale ${k} in preload)`);
    }
    let key = f.key;
    if (p.mode === 'shade' && opts.ramp) key = rampTexture(scene, key, opts.ramp);
    const obj = makeLayer(scene, p, f, key);
    c.add(obj);
    nk.layers[o] = obj;
  }
  // content: a pivot container at the logical centre (scaled with the face) holding `inner` at -centre, so the
  // children use the outer container's local coordinates
  const pivot = scene.add.container(0, 0);
  const inner = scene.add.container(0, 0);
  pivot.add(inner);
  c.add(pivot);
  nk.pivot = pivot;
  nk.content = inner;
  nk.addContent = (...objs) => { inner.add(objs.flat()); return c; };
  nk.resize = (w, h) => { nk.width = w; nk.height = h; layout(nk); return c; };
  nk.setPressed = (on) => { nk.pressed = !!on; layout(nk); return c; };
  nk.contentRect = () => {
    // insets from the canvas (sprite) edges, which sit `overhang` outside the logical rect
    const ci = p.content || oh;
    const x0 = -nk.originX * nk.width - oh[0] + ci[0], y0 = -nk.originY * nk.height - oh[1] + ci[1];
    const w = Math.max(0, nk.width + oh[0] + oh[2] - ci[0] - ci[2]);
    const h = Math.max(0, nk.height + oh[1] + oh[3] - ci[1] - ci[3]);
    return { x: x0, y: y0, width: w, height: h, centerX: x0 + w / 2, centerY: y0 + h / 2 };
  };
  c.ninekit = nk;
  layout(nk);
  if (opts.button) makeButton(c, nk);
  return c;
}

// --------------------------------------------------------------------------------------------------- layers

function makeLayer(scene, p, f, key) {
  let obj;
  if (!f.slice_px) {
    obj = scene.add.image(0, 0, key);
    obj.ninekitKind = 'image';
  } else if (p.stretch.includes('tile')) {
    obj = scene.add.container(0, 0);
    obj.ninekitKind = 'tiles';
    addFrames(scene, key, f);
    obj.ninekitParts = [];
    const [W, H] = f.size_px, [l, t, r, b] = f.slice_px;
    const xs = [0, l, W - r, W], ys = [0, t, H - b, H];
    for (let j = 0; j < 3; j++) {
      for (let i = 0; i < 3; i++) {
        const sw = xs[i + 1] - xs[i], sh = ys[j + 1] - ys[j];
        if (sw <= 0 || sh <= 0) continue;
        const tiled = (i === 1 && p.stretch[0] === 'tile') || (j === 1 && p.stretch[1] === 'tile');
        const frame = `nk${i}${j}`;
        const part = tiled ? scene.add.tileSprite(0, 0, sw, sh, key, frame) : scene.add.image(0, 0, key, frame);
        part.setOrigin(0, 0);
        part.ninekitCell = { i, j, sw, sh, tiled };
        obj.add(part);
        obj.ninekitParts.push(part);
      }
    }
  } else {
    const [l, t, r, b] = f.slice_px;
    obj = scene.add.nineslice(0, 0, key, undefined, f.size_px[0], f.size_px[1], l, r, t, b);
    obj.ninekitKind = 'nineslice';
  }
  obj.ninekitFile = f;
  return obj;
}

function addFrames(scene, key, f) {
  const tex = scene.textures.get(key);
  const [W, H] = f.size_px, [l, t, r, b] = f.slice_px;
  const xs = [0, l, W - r, W], ys = [0, t, H - b, H];
  for (let j = 0; j < 3; j++) {
    for (let i = 0; i < 3; i++) {
      const name = `nk${i}${j}`;
      const w = xs[i + 1] - xs[i], h = ys[j + 1] - ys[j];
      if (w > 0 && h > 0 && !tex.has(name)) tex.add(name, 0, xs[i], ys[j], w, h);
    }
  }
}

function layout(nk) {
  const p = nk.piece, s = nk.scale, oh = p.overhang || [0, 0, 0, 0];
  const w = nk.width, h = nk.height;
  const bx = -nk.originX * w, by = -nk.originY * h;                // the logical box's top-left
  // the sprite rect (dp): the box plus the overhang; on a `fixed` axis the sprite's natural length, centred on
  // the box whatever length the box gets (its middle is one grid step: drawn 1:1, never stretched)
  const fx = p.slice && p.stretch[0] === 'fixed', fy = p.slice && p.stretch[1] === 'fixed';
  const sw = fx ? p.size[0] : w + oh[0] + oh[2], sh = fy ? p.size[1] : h + oh[1] + oh[3];
  const x0 = fx ? bx + (w - (p.size[0] - oh[0] - oh[2])) / 2 - oh[0] : bx - oh[0];
  const y0 = fy ? by + (h - (p.size[1] - oh[1] - oh[3])) / 2 - oh[1] : by - oh[1];
  const cx = bx + w / 2, cy = by + h / 2;                          // the logical centre: the press pivot
  const kp = nk.pressed && nk.piece.press ? nk.press : 1;
  if (nk.pivot) {
    nk.pivot.setPosition(cx, cy).setScale(kp);
    nk.content.setPosition(-cx, -cy);
  }
  for (const [o, obj] of Object.entries(nk.layers)) {
    // origin (0, 0) at the sprite's top-left; a pressed face is scaled about (cx, cy) by moving that corner (a
    // fractional origin would put the unpressed sprite off the pixel grid after Phaser's rounding)
    const k = o === 'face' ? kp : 1;
    const px = cx + k * (x0 - cx), py = cy + k * (y0 - cy);
    const f = obj.ninekitFile;
    if (obj.ninekitKind === 'image') {
      obj.setOrigin(0, 0).setPosition(px, py).setScale(k * sw / f.size_px[0], k * sh / f.size_px[1]);
    } else if (obj.ninekitKind === 'nineslice') {
      obj.setSize(sw * s, sh * s);
      obj.setOrigin(0, 0).setPosition(px, py).setScale(k / s);
    } else {
      layoutTiles(obj, f, nk.piece.stretch, sw * s, sh * s);
      obj.setPosition(px, py).setScale(k / s);
    }
  }
}

/** Places the 9 parts of a tiled layer for a TW x TH texture-px rect from the group's origin. A `tile` middle
 *  repeats from its start a whole number of times (rescaled to fit, like CSS `round`); a `stretch` one stretches. */
function layoutTiles(group, f, stretch, TW, TH) {
  const [W, H] = f.size_px, [l, t, r, b] = f.slice_px;
  const mw = W - l - r, mh = H - t - b;
  const MW = Math.max(0, TW - l - r), MH = Math.max(0, TH - t - b);
  const fit = (M, m, mode) => {
    if (m <= 0 || M <= 0) return 1;
    if (mode !== 'tile') return M / m;
    return M / (Math.max(1, Math.round(M / m)) * m);
  };
  const fx = fit(MW, mw, stretch[0]), fy = fit(MH, mh, stretch[1]);
  const X = [0, l, l + MW], Y = [0, t, t + MH];
  for (const part of group.ninekitParts) {
    const { i, j, sw, sh, tiled } = part.ninekitCell;
    const tw = i === 1 ? MW : sw, th = j === 1 ? MH : sh;
    part.setVisible(tw > 0 && th > 0);
    part.setPosition(X[i], Y[j]);
    if (tiled) {
      part.setSize(tw, th);
      part.setTileScale(i === 1 ? fx : 1, j === 1 ? fy : 1);
      part.setTilePosition(0, 0);
    } else {
      part.setScale(tw / sw, th / sh);
    }
  }
}

function makeButton(c, nk) {
  const R = globalThis.Phaser.Geom.Rectangle;
  const hit = () => {
    // a Container's hit test adds its displayOrigin (half its size) to the local point
    c.setSize(nk.width, nk.height);
    return new R((0.5 - nk.originX) * nk.width, (0.5 - nk.originY) * nk.height, nk.width, nk.height);
  };
  c.setInteractive(hit(), R.Contains);
  const resize = nk.resize;
  nk.resize = (w, h) => { resize(w, h); c.input.hitArea = hit(); return c; };
  c.on('pointerdown', () => nk.setPressed(true));
  c.on('pointerup', () => nk.setPressed(false));
  c.on('pointerout', () => nk.setPressed(false));
}

// --------------------------------------------------------------------------------------------------- shade ramps

function parseHex(c) {
  const s = c.replace('#', '');
  return [0, 2, 4].map((i) => parseInt(s.slice(i, i + 2), 16));
}

/** 256-entry RGB lookup of a ramp [[t, '#rrggbb'], ...] (linear between stops, t = shade 0..1). */
export function rampLut(stops) {
  const pts = stops.map(([t, c]) => [Number(t), parseHex(c)]).sort((a, b) => a[0] - b[0]);
  const lut = new Uint8ClampedArray(256 * 3);
  for (let v = 0; v < 256; v++) {
    const t = v / 255;
    let col = pts[pts.length - 1][1];
    if (t <= pts[0][0]) col = pts[0][1];
    else {
      for (let n = 1; n < pts.length; n++) {
        if (t <= pts[n][0]) {
          const [a0, c0] = pts[n - 1], [a1, c1] = pts[n];
          const u = a1 === a0 ? 0 : (t - a0) / (a1 - a0);
          col = c0.map((x, q) => x + (c1[q] - x) * u);
          break;
        }
      }
    }
    lut[v * 3] = Math.round(col[0]); lut[v * 3 + 1] = Math.round(col[1]); lut[v * 3 + 2] = Math.round(col[2]);
  }
  return lut;
}

function rampTexture(scene, key, stops) {
  const rk = `${key}~ramp${JSON.stringify(stops)}`;
  if (scene.textures.exists(rk)) return rk;
  const src = scene.textures.get(key).getSourceImage();
  const cv = document.createElement('canvas');
  cv.width = src.width; cv.height = src.height;
  const g = cv.getContext('2d', { willReadFrequently: true });
  g.drawImage(src, 0, 0);
  const img = g.getImageData(0, 0, cv.width, cv.height), d = img.data, lut = rampLut(stops);
  for (let i = 0; i < d.length; i += 4) {
    const v = d[i] * 3;
    d[i] = lut[v]; d[i + 1] = lut[v + 1]; d[i + 2] = lut[v + 2];
  }
  g.putImageData(img, 0, 0);
  scene.textures.addCanvas(rk, cv);
  return rk;
}
